import assert from 'node:assert/strict';
const accepted = new Set(['hermes_inbound_queue_version', 'claim_hermes_inbound_turn', 'claim_next_pending_reminder']);
let intercepted = 0;
console.log(JSON.stringify({ smokeNode: process.versions.node, pid: process.pid, nodeEnv: process.env.NODE_ENV }));
globalThis.fetch = async (input, options) => {
  const url = new URL(input instanceof Request ? input.url : input);
  const method = options?.method || (input instanceof Request ? input.method : 'GET');
  assert.equal(url.origin, 'https://container-smoke.supabase.co');
  let body;
  if (url.pathname.startsWith('/rest/v1/rpc/')) {
    const rpc = url.pathname.split('/').at(-1);
    assert.ok(accepted.has(rpc), `Unexpected RPC: ${rpc}`);
    body = rpc === 'hermes_inbound_queue_version' ? 1 : [];
  } else {
    assert.equal(method, 'GET', 'Smoke must not mutate database rows');
    assert.ok(['/rest/v1/hermes_inbound_turns', '/rest/v1/reminders', '/rest/v1/users', '/rest/v1/user_integrations'].includes(url.pathname), `Unexpected table: ${url.pathname}`);
    body = [];
  }
  intercepted++;
  console.log(JSON.stringify({ syntheticRequest: intercepted, method, path: url.pathname }));
  return new Response(JSON.stringify(body), { status: 200, headers: { 'content-type': 'application/json' } });
};
process.on('exit', code => console.log(JSON.stringify({ smokeExitCode: code, syntheticRequests: intercepted })));
